"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

interface Document {
    id: string;
    title: string;
    fileUrl: string;
    documentType: string;
    createdAt: string;
}

export default function DocumentsAdminPage() {
    const [docs, setDocs] = useState<Document[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    
    const [title, setTitle] = useState("");
    const [file, setFile] = useState<File | null>(null);
    const [documentType, setDocumentType] = useState("LEGISLATION");
    const [message, setMessage] = useState("");
    const router = useRouter();

    const fetchDocs = async () => {
        try {
            const res = await fetch("/api/documents");
            if (res.ok) {
                setDocs(await res.json());
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchDocs(); }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!file && !title) return;
        setSaving(true);
        setMessage("");

        const formData = new FormData();
        formData.append("title", title);
        formData.append("documentType", documentType);
        if (file) formData.append("file", file);

        try {
            const res = await fetch("/api/documents", {
                method: "POST",
                body: formData,
            });

            if (res.ok) {
                setMessage("Амжилттай хуулагдлаа!");
                setTitle("");
                setFile(null);
                (document.getElementById("file-upload") as HTMLInputElement).value = "";
                fetchDocs();
            } else {
                setMessage("Алдаа гарлаа.");
            }
        } catch (error) {
            setMessage("Алдаа гарлаа.");
        } finally {
            setSaving(false);
            setTimeout(() => setMessage(""), 3000);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Устгах уу?")) return;
        await fetch(`/api/documents/${id}`, { method: "DELETE" });
        fetchDocs();
    };

    if (loading) return <div className="p-10 text-center animate-pulse">Уншиж байна...</div>;

    return (
        <div className="space-y-8">
            <div>
                <h1 className="text-3xl font-bold tracking-tight">Хууль тогтоомж / Файл</h1>
                <p className="text-muted-foreground">PDF файлуудыг системд хуулж нийтлэх.</p>
            </div>

            <div className="grid md:grid-cols-3 gap-8">
                <div className="md:col-span-1">
                    <form onSubmit={handleSubmit} className="space-y-4 p-6 border rounded-xl bg-card">
                        <h2 className="text-xl font-semibold mb-4">Шинээр нэмэх</h2>
                        {message && <div className="p-3 text-sm rounded bg-green-50 text-green-700">{message}</div>}
                        
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Гарчиг *</label>
                            <input required value={title} onChange={(e) => setTitle(e.target.value)} className="flex h-10 w-full rounded-md border border-input px-3 py-2 text-sm" />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Файл хуулах (PDF) *</label>
                            <input required id="file-upload" type="file" accept=".pdf,.doc,.docx" onChange={(e) => setFile(e.target.files?.[0] || null)} className="flex w-full rounded-md border border-slate-200 px-3 py-2 text-sm file:mr-4 file:bg-slate-100" />
                        </div>
                        <button type="submit" disabled={saving} className="w-full flex justify-center rounded-md bg-blue-600 text-white hover:bg-blue-700 h-10 px-4 py-2 mt-4">
                            {saving ? "Хуулж байна..." : "Файл оруулах"}
                        </button>
                    </form>
                </div>

                <div className="md:col-span-2">
                    <div className="border rounded-xl bg-white">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 border-b">
                                <tr>
                                    <th className="px-6 py-3">Гарчиг</th>
                                    <th className="px-6 py-3">Огноо</th>
                                    <th className="px-6 py-3">Үйлдэл</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {docs.length === 0 ? (
                                    <tr><td colSpan={3} className="px-6 py-8 text-center text-slate-500">Мэдээлэл олдсонгүй</td></tr>
                                ) : (
                                    docs.map(doc => (
                                        <tr key={doc.id} className="hover:bg-slate-50">
                                            <td className="px-6 py-4 font-medium">
                                                <a href={doc.fileUrl} target="_blank" className="text-indigo-600 hover:underline">
                                                    {doc.title}
                                                </a>
                                            </td>
                                            <td className="px-6 py-4 text-slate-500">{new Date(doc.createdAt).toLocaleDateString()}</td>
                                            <td className="px-6 py-4">
                                                <button onClick={() => handleDelete(doc.id)} className="text-red-500 hover:text-red-700 font-medium">
                                                    Устгах
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
}
